package view;
import controller.TeacherController; import model.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*;
public class TeacherView extends DashboardView {
 private final TeacherController controller; private final Runnable logout; private DefaultTableModel studentsModel,performanceModel; private JTable studentsTable,performanceTable;
 public TeacherView(TeacherController c,String name,Runnable logout){super("Teacher",name);this.controller=c;this.logout=logout;buildPages();refreshStudents();setVisible(true);} protected void onLogout(){logout.run();}
 protected void buildNavigation(JPanel side){addNav(side,"Overview","Dashboard");addNav(side,"Students","Students");addNav(side,"Attendance","Attendance");addNav(side,"Marks & grades","Marks");}
 private void buildPages(){JPanel home=page("Welcome, Teacher","Manage student attendance and academic performance.");JPanel info=cardPanel();info.add(new JLabel("Use the navigation menu to view students, record attendance and enter marks."),BorderLayout.NORTH);home.add(info,BorderLayout.CENTER);addPage("Dashboard",home);
 studentsModel=model("Student ID","Name","Class","Attendance");studentsTable=new JTable(studentsModel);addPage("Students",tablePage("Students","Student directory",studentsTable));
 JPanel attendance=page("Record attendance","Select a student and record today's attendance.");JPanel a=cardPanel();JButton present=new JButton("Mark present"),absent=new JButton("Mark absent");JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.add(present);actions.add(absent);a.add(new JLabel("Select a student from the Students page first."),BorderLayout.NORTH);a.add(actions,BorderLayout.CENTER);present.addActionListener(e->attendanceAction(true));absent.addActionListener(e->attendanceAction(false));attendance.add(a,BorderLayout.CENTER);addPage("Attendance",attendance);
 performanceModel=model("Student ID","Subject","Marks","Grade");performanceTable=new JTable(performanceModel);JPanel marks=page("Marks & grades","Enter marks or view a student's performance.");JPanel b=cardPanel();JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton enter=new JButton("Enter marks"),view=new JButton("View performance");bar.add(enter);bar.add(view);b.add(bar,BorderLayout.NORTH);b.add(new JScrollPane(performanceTable),BorderLayout.CENTER);marks.add(b,BorderLayout.CENTER);enter.addActionListener(e->enterMarks());view.addActionListener(e->loadPerformance());addPage("Marks",marks);}
 private JPanel tablePage(String title,String sub,JTable table){JPanel p=page(title,sub);JPanel b=cardPanel();b.add(new JScrollPane(table),BorderLayout.CENTER);p.add(b,BorderLayout.CENTER);return p;}
 private DefaultTableModel model(String...c){return new DefaultTableModel(c,0){public boolean isCellEditable(int r,int c){return false;}};}
 private void refreshStudents(){studentsModel.setRowCount(0);for(Student s:controller.getStudents())studentsModel.addRow(new Object[]{s.getStudentId(),s.getName(),s.getClassName(),String.format("%.1f%%",s.getAttendance())});}
 private int selectedStudentId(){int row=studentsTable.getSelectedRow();if(row<0){String val=JOptionPane.showInputDialog(this,"Enter student ID:");if(val==null)return -1;try{return Integer.parseInt(val.trim());}catch(Exception e){error("Enter a valid student ID.");return -1;}}return Integer.parseInt(studentsTable.getValueAt(row,0).toString());}
 private void attendanceAction(boolean present){int id=selectedStudentId();if(id<0)return;if(controller.markAttendance(id,present)){info("Attendance recorded.");refreshStudents();}else error("Student ID not found.");}
 private void enterMarks(){JTextField id=new JTextField(),subject=new JTextField(),marks=new JTextField();Object[] f={"Student ID",id,"Subject",subject,"Marks (0-100)",marks};if(JOptionPane.showConfirmDialog(this,f,"Enter marks",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{boolean ok=controller.enterMarks(Integer.parseInt(id.getText().trim()),subject.getText(),Double.parseDouble(marks.getText().trim()));if(ok){info("Marks saved successfully.");loadPerformanceFor(Integer.parseInt(id.getText().trim()));}else error("Check student ID, subject and marks (0-100).");}catch(Exception e){error("Please enter valid numeric values.");}}
 private void loadPerformance(){int id=selectedStudentId();if(id>=0)loadPerformanceFor(id);}
 private void loadPerformanceFor(int id){performanceModel.setRowCount(0);for(Marks m:controller.getMarksForStudent(id))performanceModel.addRow(new Object[]{m.getStudentId(),m.getSubject(),m.getMarks(),m.getGrade()});if(performanceModel.getRowCount()==0)info("No marks found for this student.");}
}
